*{margin:0;padding:0;box-sizing:border-box}
body{min-height:100vh;background:linear-gradient(135deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%);font-family:'Rubik',sans-serif;color:#fff}
*::-webkit-scrollbar{width:8px}*::-webkit-scrollbar-track{background:rgba(0,0,0,0.1);border-radius:4px}*::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#FF6B6B,#FFE66D);border-radius:4px}
.loading-container{min-height:100vh;display:flex;align-items:center;justify-content:center;flex-direction:column}
.pokeball-loader{width:100px;height:100px;animation:spin 1s linear infinite}
.pokeball-top{width:100px;height:50px;background:#ff1a1a;border-radius:50px 50px 0 0;border:4px solid #222;border-bottom:none}
.pokeball-middle{width:100px;height:12px;background:#222;display:flex;align-items:center;justify-content:center}
.pokeball-button{width:24px;height:24px;background:#fff;border-radius:50%;border:4px solid #222;margin-top:-6px}
.pokeball-bottom{width:100px;height:50px;background:#fff;border-radius:0 0 50px 50px;border:4px solid #222;border-top:none}
.loading-title{font-family:'Righteous',cursive;font-size:24px;margin-top:30px;margin-bottom:10px}
.loading-status{color:#888;font-size:14px;margin-bottom:20px}
.progress-bar{width:300px;height:12px;background:rgba(255,255,255,0.1);border-radius:6px;overflow:hidden}
.progress-fill{height:100%;background:linear-gradient(90deg,#FF6B6B,#FFE66D);border-radius:6px;transition:width 0.3s ease;width:0%}
.progress-text{color:#888;margin-top:12px;font-size:14px}
@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
@keyframes bounce{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-5px) scale(1.02)}}
@keyframes pulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.05);opacity:0.8}}
.app-container{display:none}
header{padding:40px 20px 30px;text-align:center;background:linear-gradient(180deg,rgba(0,0,0,0.3) 0%,transparent 100%)}
.logo-section{display:flex;align-items:center;justify-content:center;gap:16px;margin-bottom:12px}
.mini-pokeball{width:40px;height:40px;flex-shrink:0}
.mini-pokeball-top{width:40px;height:20px;background:#ff1a1a;border-radius:20px 20px 0 0;border:3px solid #222;border-bottom:none}
.mini-pokeball-line{width:40px;height:6px;background:#222}
.mini-pokeball-bottom{width:40px;height:20px;background:#fff;border-radius:0 0 20px 20px;border:3px solid #222;border-top:none}
h1{font-size:clamp(28px,5vw,48px);font-family:'Righteous',cursive;background:linear-gradient(135deg,#FFE66D 0%,#FF6B6B 50%,#4ECDC4 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.subtitle{color:#888;font-size:16px}
.team-section{padding:20px;max-width:1400px;margin:0 auto}
.team-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;flex-wrap:wrap;gap:12px}
.team-title{font-size:24px;font-family:'Righteous',cursive;color:#FFE66D}
.clear-team-btn{padding:10px 20px;background:rgba(255,107,107,0.2);border:2px solid #FF6B6B;border-radius:25px;color:#FF6B6B;cursor:pointer;font-weight:600;font-family:'Rubik',sans-serif;transition:all 0.3s ease}
.clear-team-btn:hover{background:#FF6B6B;color:#fff}
.team-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;max-width:1000px;margin:0 auto}
.team-slot{aspect-ratio:1;border-radius:20px;border:3px dashed rgba(255,255,255,0.2);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:16px;transition:all 0.3s ease;cursor:pointer;position:relative;background:rgba(255,255,255,0.03)}
.team-slot:hover{transform:scale(1.05)}.team-slot.filled{border-style:solid}
.team-slot .sprite{width:80px;height:80px;object-fit:contain;filter:drop-shadow(0 4px 8px rgba(0,0,0,0.3))}
.team-slot .name{font-size:14px;font-weight:600;text-transform:capitalize;margin-top:8px;text-align:center}
.team-slot .types{display:flex;gap:6px;margin-top:8px}
.team-slot .mini-type{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px}
.team-slot .remove-hint{position:absolute;bottom:8px;font-size:10px;color:rgba(255,255,255,0.5);opacity:0;transition:opacity 0.3s ease}
.team-slot:hover .remove-hint{opacity:1}
.empty-slot{display:flex;flex-direction:column;align-items:center;gap:8px;color:rgba(255,255,255,0.3)}
.empty-slot .icon{font-size:32px;font-weight:300}.empty-slot .text{font-size:12px;text-transform:uppercase;letter-spacing:2px}
.filter-section{padding:20px;max-width:1400px;margin:0 auto;background:rgba(0,0,0,0.2);border-radius:24px;width:calc(100% - 40px)}
.search-container{position:relative;max-width:500px;margin:0 auto 24px}
.search-icon{position:absolute;left:20px;top:50%;transform:translateY(-50%);font-size:20px}
.search-input{width:100%;padding:16px 50px;font-size:16px;border:2px solid rgba(255,255,255,0.1);border-radius:50px;background:rgba(255,255,255,0.05);color:#fff;outline:none;transition:all 0.3s ease;font-family:'Rubik',sans-serif}
.search-input:focus{border-color:rgba(255,255,255,0.3);background:rgba(255,255,255,0.1)}
.search-input::placeholder{color:rgba(255,255,255,0.4)}
.clear-search{position:absolute;right:16px;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.1);border:none;color:#fff;width:28px;height:28px;border-radius:50%;cursor:pointer;display:none;align-items:center;justify-content:center;font-size:14px}
.clear-search.visible{display:flex}
.dropdown-filters{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin-bottom:24px}
.dropdown-container{position:relative}
.dropdown-btn{display:flex;align-items:center;gap:8px;padding:10px 16px;background:rgba(255,255,255,0.05);border:2px solid rgba(255,255,255,0.15);border-radius:30px;color:#fff;cursor:pointer;font-family:'Rubik',sans-serif;font-size:13px;transition:all 0.3s ease;min-width:140px;justify-content:space-between}
.dropdown-btn:hover{border-color:rgba(255,255,255,0.3);background:rgba(255,255,255,0.1)}
.dropdown-btn.has-selection{border-color:#4ECDC4;background:rgba(78,205,196,0.15)}
.dropdown-btn .arrow{transition:transform 0.3s ease;font-size:10px}.dropdown-btn.open .arrow{transform:rotate(180deg)}
.dropdown-menu{position:absolute;top:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#1a1a2e;border:2px solid rgba(255,255,255,0.15);border-radius:16px;padding:8px;min-width:200px;max-height:300px;overflow-y:auto;z-index:100;display:none;box-shadow:0 10px 40px rgba(0,0,0,0.5)}
.dropdown-menu.open{display:block}
.dropdown-item{padding:10px 16px;border-radius:10px;cursor:pointer;transition:all 0.2s ease;font-size:13px;display:flex;align-items:center;gap:8px}
.dropdown-item:hover{background:rgba(255,255,255,0.1)}
.dropdown-item.selected{background:rgba(78,205,196,0.2);color:#4ECDC4}
.dropdown-item .check{opacity:0;color:#4ECDC4}.dropdown-item.selected .check{opacity:1}
.filter-group{margin-bottom:24px;text-align:center}.filter-group:last-child{margin-bottom:0}
.filter-label{display:block;margin-bottom:12px;color:#888;font-size:14px;text-transform:uppercase;letter-spacing:2px}
.filter-buttons{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.filter-btn{display:flex;align-items:center;gap:6px;padding:8px 14px;border:2px solid rgba(255,255,255,0.2);border-radius:25px;cursor:pointer;font-size:13px;font-weight:500;transition:all 0.2s ease;text-transform:capitalize;font-family:'Rubik',sans-serif;background:rgba(255,255,255,0.1);color:#aaa}
.filter-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,0,0,0.3)}
.filter-btn.active{color:#fff;transform:scale(1.05);box-shadow:0 4px 15px rgba(0,0,0,0.4)}
.filter-btn .filter-icon{font-size:14px}.filter-btn .filter-name{font-size:12px}
.type-match-toggle{display:none;align-items:center;justify-content:center;gap:12px;margin-top:16px;padding:12px 20px;background:rgba(255,255,255,0.05);border-radius:30px;width:fit-content;margin-left:auto;margin-right:auto}
.type-match-toggle.visible{display:flex}.type-match-toggle span{font-size:13px;color:#888}
.toggle-switch{display:flex;background:rgba(0,0,0,0.3);border-radius:20px;padding:4px}
.toggle-option{padding:8px 16px;border-radius:16px;cursor:pointer;font-size:12px;font-weight:600;transition:all 0.3s ease;color:#888}
.toggle-option.active{background:linear-gradient(135deg,#FF6B6B,#FFE66D);color:#000}
.active-filters{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:16px}
.filter-pill{display:flex;align-items:center;gap:6px;padding:6px 12px;background:rgba(78,205,196,0.2);border:1px solid #4ECDC4;border-radius:20px;font-size:12px;color:#4ECDC4}
.filter-pill .remove{cursor:pointer;font-weight:bold;opacity:0.7;transition:opacity 0.2s}.filter-pill .remove:hover{opacity:1}
.clear-filters{margin-top:20px;padding:10px 20px;background:transparent;border:2px solid rgba(255,255,255,0.3);border-radius:25px;color:#fff;cursor:pointer;font-size:13px;transition:all 0.3s ease;font-family:'Rubik',sans-serif;display:none}
.clear-filters.visible{display:inline-block}.clear-filters:hover{background:rgba(255,255,255,0.1)}
.pokemon-section{padding:30px 20px 50px;max-width:1400px;margin:0 auto}
.result-count{text-align:center;color:#888;margin-bottom:24px;font-size:14px}
.pokemon-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:20px}
.pokemon-card{border-radius:20px;border:2px solid;padding:16px;transition:all 0.3s ease;position:relative;overflow:hidden;cursor:pointer}
.pokemon-card:hover{transform:translateY(-8px) scale(1.02);box-shadow:0 20px 40px rgba(0,0,0,0.3)}
.pokemon-card:hover .pokemon-sprite{animation:bounce 0.6s ease-in-out infinite}
.pokemon-card.in-team{opacity:0.5;cursor:not-allowed}.pokemon-card.team-full:not(.in-team){cursor:not-allowed}
.card-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.pokemon-number{font-size:12px;color:rgba(255,255,255,0.5);font-weight:600}
.pokemon-badges{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}.card-badge{font-size:8px;padding:2px 5px;border-radius:6px;font-weight:600}
.in-team-badge{background:#4ECDC4;color:#000}.evolved-badge{background:#FFE66D;color:#000}
.legendary-badge{background:linear-gradient(135deg,#FFD700,#FFA500);color:#000}
.mythical-badge{background:linear-gradient(135deg,#FF69B4,#DA70D6);color:#000}
.pseudo-badge{background:linear-gradient(135deg,#9370DB,#6A5ACD);color:#fff}
.mega-badge{background:linear-gradient(135deg,#FF4444,#CC0000);color:#fff}
.gmax-badge{background:linear-gradient(135deg,#FF1493,#C71585);color:#fff}
.sprite-container{position:relative;display:flex;justify-content:center;padding:10px 0}
.sprite-glow{position:absolute;width:60px;height:60px;border-radius:50%;filter:blur(20px);opacity:0.4;top:50%;left:50%;transform:translate(-50%,-50%)}
.pokemon-sprite{width:96px;height:96px;object-fit:contain;position:relative;z-index:1;image-rendering:pixelated;filter:drop-shadow(0 4px 8px rgba(0,0,0,0.3))}
.pokemon-name{font-size:15px;font-weight:600;text-transform:capitalize;text-align:center;margin:8px 0;color:#fff}
.type-container{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}
.type-badge{display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:15px;font-size:11px;font-weight:600;text-transform:capitalize;color:#fff;transition:transform 0.2s ease;text-shadow:0 1px 2px rgba(0,0,0,0.3)}
.type-badge:hover{transform:scale(1.1)}
.add-hint{position:absolute;bottom:8px;right:8px;width:24px;height:24px;background:linear-gradient(135deg,#4ECDC4,#44a8a0);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:bold;color:#fff;opacity:0;transition:all 0.3s ease;box-shadow:0 2px 8px rgba(78,205,196,0.4);cursor:pointer}
.pokemon-card:hover .add-hint{opacity:1}
.pokemon-card:hover .add-hint:hover{transform:scale(1.15);box-shadow:0 4px 12px rgba(78,205,196,0.6)}
.no-results{text-align:center;padding:60px 20px;color:#888;display:none}.no-results.visible{display:block}
.no-results-icon{font-size:64px;display:block;margin-bottom:20px}
.reset-btn{margin-top:20px;padding:12px 30px;background:#4ECDC4;border:none;border-radius:25px;color:#000;cursor:pointer;font-weight:600;font-size:14px;transition:all 0.3s ease;font-family:'Rubik',sans-serif}
.reset-btn:hover{transform:scale(1.05);box-shadow:0 8px 25px rgba(78,205,196,0.4)}

js_code:
const TYPE_COLORS={normal:'#A8A878',fire:'#F08030',water:'#6890F0',electric:'#F8D030',grass:'#78C850',ice:'#98D8D8',fighting:'#C03028',poison:'#A040A0',ground:'#E0C068',flying:'#A890F0',psychic:'#F85888',bug:'#A8B820',rock:'#B8A038',ghost:'#705898',dragon:'#7038F8',dark:'#705848',steel:'#B8B8D0',fairy:'#EE99AC'};
const TYPE_ICONS={normal:'⬜',fire:'🔥',water:'💧',electric:'⚡',grass:'🌿',ice:'❄️',fighting:'👊',poison:'☠️',ground:'🏔️',flying:'🦅',psychic:'🔮',bug:'🐛',rock:'🪨',ghost:'👻',dragon:'🐉',dark:'🌑',steel:'⚙️',fairy:'✨'};
const EGG_GROUPS=['monster','water1','water2','water3','bug','flying','field','fairy','grass','human-like','mineral','amorphous','ditto','dragon','undiscovered'];
const EGG_GROUP_NAMES={'monster':'Monster','water1':'Water 1','water2':'Water 2','water3':'Water 3','bug':'Bug','flying':'Flying','field':'Field','fairy':'Fairy','grass':'Grass','human-like':'Human-Like','mineral':'Mineral','amorphous':'Amorphous','ditto':'Ditto','dragon':'Dragon','undiscovered':'Undiscovered'};
const POKEMON_TYPES=Object.keys(TYPE_COLORS);

// Pseudo-legendaries by name
const PSEUDO_LEGENDARIES=['dragonite','tyranitar','salamence','metagross','garchomp','hydreigon','goodra','kommo-o','dragapult','baxcalibur'];

let allPokemon=[],speciesData={},evolutionData={},team=[],selectedTypes=[],selectedGeneration=null,selectedEggGroup=null,selectedEvolution='all',selectedCategory='all',selectedForm='all',typeMatchMode='any',searchQuery='';
const $=id=>document.getElementById(id);

async function init(){generateTypeButtons();generateTeamSlots();generateDropdownMenus();setupEventListeners();await fetchAllPokemon();}

function generateTypeButtons(){$('typeButtons').innerHTML=POKEMON_TYPES.map(t=>`<button class="filter-btn" data-type="${t}" style="border-color:${TYPE_COLORS[t]}"><span class="filter-icon">${TYPE_ICONS[t]}</span><span class="filter-name">${t}</span></button>`).join('');}

function generateTeamSlots(){$('teamGrid').innerHTML=Array(6).fill(0).map((_,i)=>`<div class="team-slot" data-slot="${i}"><div class="empty-slot"><span class="icon">+</span><span class="text">Empty</span></div></div>`).join('');}

function generateDropdownMenus(){
  $('generationMenu').innerHTML=`<div class="dropdown-item" data-value=""><span class="check">✓</span>All Generations</div>${Array.from({length:9},(_,i)=>`<div class="dropdown-item" data-value="${i+1}"><span class="check">✓</span>Generation ${i+1}</div>`).join('')}`;
  $('eggGroupMenu').innerHTML=`<div class="dropdown-item" data-value=""><span class="check">✓</span>All Egg Groups</div>${EGG_GROUPS.map(g=>`<div class="dropdown-item" data-value="${g}"><span class="check">✓</span>${EGG_GROUP_NAMES[g]}</div>`).join('')}`;
}

function setupEventListeners(){
  $('searchInput').addEventListener('input',e=>{searchQuery=e.target.value;$('clearSearch').classList.toggle('visible',searchQuery.length>0);renderPokemon();});
  $('clearSearch').addEventListener('click',()=>{searchQuery='';$('searchInput').value='';$('clearSearch').classList.remove('visible');renderPokemon();});
  $('typeButtons').addEventListener('click',e=>{const btn=e.target.closest('.filter-btn');if(!btn)return;const type=btn.dataset.type;if(selectedTypes.includes(type)){selectedTypes=selectedTypes.filter(t=>t!==type);btn.classList.remove('active');btn.style.backgroundColor='rgba(255,255,255,0.1)';btn.style.color='#aaa';}else{selectedTypes.push(type);btn.classList.add('active');btn.style.backgroundColor=TYPE_COLORS[type];btn.style.color='#fff';}$('typeMatchToggle').classList.toggle('visible',selectedTypes.length>1);updateFiltersUI();renderPokemon();});
  $('typeMatchToggle').addEventListener('click',e=>{const opt=e.target.closest('.toggle-option');if(!opt)return;$('typeMatchToggle').querySelectorAll('.toggle-option').forEach(o=>o.classList.remove('active'));opt.classList.add('active');typeMatchMode=opt.dataset.mode;renderPokemon();});
  setupDropdown('generationBtn','generationMenu',v=>{selectedGeneration=v?parseInt(v):null;updateFiltersUI();renderPokemon();});
  setupDropdown('eggGroupBtn','eggGroupMenu',v=>{selectedEggGroup=v||null;updateFiltersUI();renderPokemon();});
  setupDropdown('evolutionBtn','evolutionMenu',v=>{selectedEvolution=v||'all';updateFiltersUI();renderPokemon();});
  setupDropdown('categoryBtn','categoryMenu',v=>{selectedCategory=v||'all';updateFiltersUI();renderPokemon();});
  setupDropdown('formBtn','formMenu',v=>{selectedForm=v||'all';updateFiltersUI();renderPokemon();});
  document.addEventListener('click',e=>{if(!e.target.closest('.dropdown-container')){document.querySelectorAll('.dropdown-menu').forEach(m=>m.classList.remove('open'));document.querySelectorAll('.dropdown-btn').forEach(b=>b.classList.remove('open'));}});
  $('clearFilters').addEventListener('click',resetAllFilters);$('resetBtn').addEventListener('click',resetAllFilters);
  $('clearTeamBtn').addEventListener('click',()=>{team=[];updateTeamDisplay();renderPokemon();});
  $('teamGrid').addEventListener('click',e=>{const slot=e.target.closest('.team-slot');if(!slot||!slot.classList.contains('filled'))return;team.splice(parseInt(slot.dataset.slot),1);updateTeamDisplay();renderPokemon();});
  $('pokemonGrid').addEventListener('click',e=>{const card=e.target.closest('.pokemon-card');if(!card||card.classList.contains('in-team')||team.length>=6)return;const pokemon=allPokemon.find(p=>p.id===parseInt(card.dataset.id)&&p.name===card.dataset.name);if(pokemon&&!team.find(p=>p.id===pokemon.id&&p.name===pokemon.name)){team.push(pokemon);updateTeamDisplay();renderPokemon();}});
  $('activeFilters').addEventListener('click',e=>{const pill=e.target.closest('.filter-pill');if(!pill)return;const{filterType,filterValue}=pill.dataset;if(filterType==='type'){selectedTypes=selectedTypes.filter(t=>t!==filterValue);const btn=document.querySelector(`.filter-btn[data-type="${filterValue}"]`);if(btn){btn.classList.remove('active');btn.style.backgroundColor='rgba(255,255,255,0.1)';btn.style.color='#aaa';}$('typeMatchToggle').classList.toggle('visible',selectedTypes.length>1);}else if(filterType==='generation'){selectedGeneration=null;$('generationBtn').classList.remove('has-selection');$('generationBtn').querySelector('span').textContent='🎮 Generation';}else if(filterType==='eggGroup'){selectedEggGroup=null;$('eggGroupBtn').classList.remove('has-selection');$('eggGroupBtn').querySelector('span').textContent='🥚 Egg Group';}else if(filterType==='evolution'){selectedEvolution='all';$('evolutionBtn').classList.remove('has-selection');$('evolutionBtn').querySelector('span').textContent='⭐ Evolution';}else if(filterType==='category'){selectedCategory='all';$('categoryBtn').classList.remove('has-selection');$('categoryBtn').querySelector('span').textContent='👑 Category';}else if(filterType==='form'){selectedForm='all';$('formBtn').classList.remove('has-selection');$('formBtn').querySelector('span').textContent='🔄 Form';}updateFiltersUI();renderPokemon();});
}

function setupDropdown(btnId,menuId,onSelect){const btn=$(btnId),menu=$(menuId);btn.addEventListener('click',e=>{e.stopPropagation();const isOpen=menu.classList.contains('open');document.querySelectorAll('.dropdown-menu').forEach(m=>m.classList.remove('open'));document.querySelectorAll('.dropdown-btn').forEach(b=>b.classList.remove('open'));if(!isOpen){menu.classList.add('open');btn.classList.add('open');}});menu.addEventListener('click',e=>{const item=e.target.closest('.dropdown-item');if(!item)return;const value=item.dataset.value;menu.querySelectorAll('.dropdown-item').forEach(i=>i.classList.remove('selected'));item.classList.add('selected');if(value&&value!=='all'){btn.classList.add('has-selection');btn.querySelector('span').textContent=item.textContent.trim();}else{btn.classList.remove('has-selection');const icons={'generationBtn':'🎮 Generation','eggGroupBtn':'🥚 Egg Group','evolutionBtn':'⭐ Evolution','categoryBtn':'👑 Category','formBtn':'🔄 Form'};btn.querySelector('span').textContent=icons[btnId];}menu.classList.remove('open');btn.classList.remove('open');onSelect(value);});}

function resetAllFilters(){searchQuery='';$('searchInput').value='';$('clearSearch').classList.remove('visible');selectedTypes=[];document.querySelectorAll('.filter-btn').forEach(btn=>{btn.classList.remove('active');btn.style.backgroundColor='rgba(255,255,255,0.1)';btn.style.color='#aaa';});$('typeMatchToggle').classList.remove('visible');selectedGeneration=null;selectedEggGroup=null;selectedEvolution='all';selectedCategory='all';selectedForm='all';document.querySelectorAll('.dropdown-btn').forEach(btn=>btn.classList.remove('has-selection'));$('generationBtn').querySelector('span').textContent='🎮 Generation';$('eggGroupBtn').querySelector('span').textContent='🥚 Egg Group';$('evolutionBtn').querySelector('span').textContent='⭐ Evolution';$('categoryBtn').querySelector('span').textContent='👑 Category';$('formBtn').querySelector('span').textContent='🔄 Form';document.querySelectorAll('.dropdown-item').forEach(item=>item.classList.remove('selected'));updateFiltersUI();renderPokemon();}

function updateFiltersUI(){const hasFilters=selectedTypes.length>0||selectedGeneration||selectedEggGroup||selectedEvolution!=='all'||selectedCategory!=='all'||selectedForm!=='all';$('clearFilters').classList.toggle('visible',hasFilters);let pills=selectedTypes.map(type=>`<div class="filter-pill" data-filter-type="type" data-filter-value="${type}">${TYPE_ICONS[type]} ${type}<span class="remove">×</span></div>`);if(selectedGeneration)pills.push(`<div class="filter-pill" data-filter-type="generation" data-filter-value="${selectedGeneration}">🎮 Gen ${selectedGeneration}<span class="remove">×</span></div>`);if(selectedEggGroup)pills.push(`<div class="filter-pill" data-filter-type="eggGroup" data-filter-value="${selectedEggGroup}">🥚 ${EGG_GROUP_NAMES[selectedEggGroup]}<span class="remove">×</span></div>`);if(selectedEvolution!=='all'){const labels={'fully-evolved':'Fully Evolved','not-fully-evolved':'Not Fully Evolved','no-evolution':'No Evolutions'};pills.push(`<div class="filter-pill" data-filter-type="evolution" data-filter-value="${selectedEvolution}">⭐ ${labels[selectedEvolution]}<span class="remove">×</span></div>`);}if(selectedCategory!=='all'){const labels={'legendary':'Legendary','mythical':'Mythical','pseudo':'Pseudo-Legendary','regular':'Regular'};pills.push(`<div class="filter-pill" data-filter-type="category" data-filter-value="${selectedCategory}">👑 ${labels[selectedCategory]}<span class="remove">×</span></div>`);}if(selectedForm!=='all'){const labels={'base':'Base Forms','mega':'Mega','gmax':'Gigantamax'};pills.push(`<div class="filter-pill" data-filter-type="form" data-filter-value="${selectedForm}">🔄 ${labels[selectedForm]}<span class="remove">×</span></div>`);}$('activeFilters').innerHTML=pills.join('');}

async function fetchAllPokemon(){try{
  $('loadingStatus').textContent='Loading Pokémon data...';

  // Fetch base Pokemon (limit to 1025 for main pokemon)
  const listResponse=await fetch('https://pokeapi.co/api/v2/pokemon?limit=1500');
  const listData=await listResponse.json();

  const batchSize=50;
  const pokemonToFetch=listData.results;

  for(let i=0;i<pokemonToFetch.length;i+=batchSize){
    const batch=pokemonToFetch.slice(i,i+batchSize);
    const results=await Promise.all(batch.map(p=>fetch(p.url).then(r=>r.json()).catch(()=>null)));
    results.forEach(pokemon=>{
      if(!pokemon)return;
      const name=pokemon.name;
      const isMega=name.includes('-mega');
      const isGmax=name.includes('-gmax');
      const isSpecialForm=isMega||isGmax;

      // Skip other alternate forms we don't want
      if(!isSpecialForm && pokemon.id>10000) return;

      allPokemon.push({
        id:pokemon.id,
        baseId:pokemon.id>10000?parseInt(pokemon.species.url.split('/').slice(-2)[0]):pokemon.id,
        name:pokemon.name,
        displayName:formatName(pokemon.name),
        types:pokemon.types.map(t=>t.type.name),
        sprite:pokemon.sprites.front_default||pokemon.sprites.other['official-artwork'].front_default,
        artwork:pokemon.sprites.other['official-artwork'].front_default||pokemon.sprites.front_default,
        speciesUrl:pokemon.species.url,
        isMega,
        isGmax
      });
    });
    const progress=Math.round((Math.min(i+batchSize,pokemonToFetch.length)/pokemonToFetch.length)*45);
    $('progressFill').style.width=`${progress}%`;
    $('progressText').textContent=progress;
  }

  $('loadingStatus').textContent='Loading species data...';
  const uniqueSpeciesUrls=[...new Set(allPokemon.map(p=>p.speciesUrl))];
  const speciesBatchSize=100;

  for(let i=0;i<uniqueSpeciesUrls.length;i+=speciesBatchSize){
    const batch=uniqueSpeciesUrls.slice(i,i+speciesBatchSize);
    const results=await Promise.all(batch.map(url=>fetch(url).then(r=>r.json()).catch(()=>null)));
    results.forEach((species,index)=>{
      if(!species)return;
      const url=batch[index];
      const genMatch=species.generation.url.match(/\/(\d+)\//);
      speciesData[url]={
        eggGroups:species.egg_groups.map(eg=>eg.name),
        evolutionChainUrl:species.evolution_chain?.url,
        generation:genMatch?parseInt(genMatch[1]):1,
        isLegendary:species.is_legendary,
        isMythical:species.is_mythical
      };
    });
    const progress=45+Math.round(((i+speciesBatchSize)/uniqueSpeciesUrls.length)*35);
    $('progressFill').style.width=`${Math.min(progress,80)}%`;
    $('progressText').textContent=Math.min(progress,80);
  }

  // Apply species data to pokemon
  allPokemon.forEach(pokemon=>{
    const species=speciesData[pokemon.speciesUrl];
    if(species){
      pokemon.generation=species.generation;
      pokemon.eggGroups=species.eggGroups;
      pokemon.isLegendary=species.isLegendary;
      pokemon.isMythical=species.isMythical;
      pokemon.isPseudo=PSEUDO_LEGENDARIES.includes(pokemon.name.split('-')[0]);
    }
  });

  $('loadingStatus').textContent='Loading evolution data...';
  const uniqueChainUrls=[...new Set(Object.values(speciesData).map(s=>s.evolutionChainUrl).filter(Boolean))];
  const chainBatchSize=50;

  for(let i=0;i<uniqueChainUrls.length;i+=chainBatchSize){
    const batch=uniqueChainUrls.slice(i,i+chainBatchSize);
    const results=await Promise.all(batch.map(url=>fetch(url).then(r=>r.json()).catch(()=>null)));
    results.forEach((chain,index)=>{if(chain)evolutionData[batch[index]]=parseEvolutionChain(chain.chain);});
  }

  allPokemon.forEach(pokemon=>{
    const species=speciesData[pokemon.speciesUrl];
    if(species?.evolutionChainUrl){
      const chain=evolutionData[species.evolutionChainUrl];
      if(chain){
        const baseName=pokemon.name.split('-')[0];
        pokemon.isFullyEvolved=chain.fullyEvolved.includes(baseName)||chain.fullyEvolved.includes(pokemon.name);
        pokemon.hasNoEvolution=chain.total===1;
      }
    }
  });

  // Sort: base forms first, then megas, then gmax
  allPokemon.sort((a,b)=>{
    if(a.baseId!==b.baseId)return a.baseId-b.baseId;
    if(!a.isMega&&!a.isGmax&&(b.isMega||b.isGmax))return -1;
    if((a.isMega||a.isGmax)&&!b.isMega&&!b.isGmax)return 1;
    if(a.isMega&&b.isGmax)return -1;
    if(a.isGmax&&b.isMega)return 1;
    return 0;
  });

  $('progressFill').style.width='100%';
  $('progressText').textContent='100';
  $('totalCount').textContent=allPokemon.length;
  $('loadingScreen').style.display='none';
  $('appContainer').style.display='block';
  renderPokemon();
}catch(error){console.error('Error:',error);$('loadingStatus').textContent='Error loading. Please refresh.';}}

function formatName(name){
  return name.replace(/-mega-x/g,' (Mega X)').replace(/-mega-y/g,' (Mega Y)').replace(/-mega/g,' (Mega)').replace(/-gmax/g,' (Gmax)').replace(/-/g,' ');
}

function parseEvolutionChain(chain){const allSpecies=[],fullyEvolved=[];function traverse(node){allSpecies.push(node.species.name);if(node.evolves_to.length===0)fullyEvolved.push(node.species.name);else node.evolves_to.forEach(traverse);}traverse(chain);return{total:allSpecies.length,fullyEvolved,allSpecies};}

function getFilteredPokemon(){return allPokemon.filter(pokemon=>{
  const baseName=pokemon.name.split('-')[0];
  if(!pokemon.name.toLowerCase().includes(searchQuery.toLowerCase())&&!pokemon.displayName.toLowerCase().includes(searchQuery.toLowerCase())&&!pokemon.baseId.toString().includes(searchQuery))return false;
  if(selectedTypes.length>0){if(typeMatchMode==='all'){if(!selectedTypes.every(t=>pokemon.types.includes(t)))return false;}else{if(!selectedTypes.some(t=>pokemon.types.includes(t)))return false;}}
  if(selectedGeneration&&pokemon.generation!==selectedGeneration)return false;
  if(selectedEggGroup&&(!pokemon.eggGroups||!pokemon.eggGroups.includes(selectedEggGroup)))return false;
  if(selectedEvolution==='fully-evolved'&&!pokemon.isFullyEvolved)return false;
  if(selectedEvolution==='not-fully-evolved'&&(pokemon.isFullyEvolved||pokemon.hasNoEvolution))return false;
  if(selectedEvolution==='no-evolution'&&!pokemon.hasNoEvolution)return false;

  // Category filter
  if(selectedCategory==='legendary'&&!pokemon.isLegendary)return false;
  if(selectedCategory==='mythical'&&!pokemon.isMythical)return false;
  if(selectedCategory==='pseudo'&&!pokemon.isPseudo)return false;
  if(selectedCategory==='regular'&&(pokemon.isLegendary||pokemon.isMythical||pokemon.isPseudo))return false;

  // Form filter
  if(selectedForm==='base'&&(pokemon.isMega||pokemon.isGmax))return false;
  if(selectedForm==='mega'&&!pokemon.isMega)return false;
  if(selectedForm==='gmax'&&!pokemon.isGmax)return false;

  return true;
});}

function renderPokemon(){const filtered=getFilteredPokemon();$('showingCount').textContent=filtered.length;if(filtered.length===0){$('pokemonGrid').innerHTML='';$('noResults').classList.add('visible');return;}$('noResults').classList.remove('visible');$('pokemonGrid').innerHTML=filtered.map(pokemon=>{const isInTeam=team.find(p=>p.id===pokemon.id&&p.name===pokemon.name);const isTeamFull=team.length>=6;const primaryColor=TYPE_COLORS[pokemon.types[0]];const secondaryColor=TYPE_COLORS[pokemon.types[1]||pokemon.types[0]];
  let badges='';
  if(isInTeam)badges+='<span class="card-badge in-team-badge">In Team</span>';
  if(pokemon.isLegendary)badges+='<span class="card-badge legendary-badge">Legend</span>';
  if(pokemon.isMythical)badges+='<span class="card-badge mythical-badge">Mythic</span>';
  if(pokemon.isPseudo)badges+='<span class="card-badge pseudo-badge">Pseudo</span>';
  if(pokemon.isMega)badges+='<span class="card-badge mega-badge">Mega</span>';
  if(pokemon.isGmax)badges+='<span class="card-badge gmax-badge">Gmax</span>';
  if(!badges&&pokemon.isFullyEvolved)badges+='<span class="card-badge evolved-badge">Final</span>';

  return`<div class="pokemon-card ${isInTeam?'in-team':''} ${isTeamFull&&!isInTeam?'team-full':''}" data-id="${pokemon.id}" data-name="${pokemon.name}" style="background:linear-gradient(145deg,${primaryColor}25 0%,${secondaryColor}15 100%);border-color:${primaryColor}"><div class="card-header"><span class="pokemon-number">#${String(pokemon.baseId).padStart(4,'0')}</span><div class="pokemon-badges">${badges}</div></div><div class="sprite-container"><div class="sprite-glow" style="background-color:${primaryColor}"></div><img src="${pokemon.sprite}" alt="${pokemon.name}" class="pokemon-sprite" loading="lazy" onerror="this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${pokemon.baseId}.png'"></div><h3 class="pokemon-name">${pokemon.displayName}</h3><div class="type-container">${pokemon.types.map(type=>`<span class="type-badge" style="background-color:${TYPE_COLORS[type]}">${TYPE_ICONS[type]} ${type}</span>`).join('')}</div>${!isInTeam&&!isTeamFull?'<div class="add-hint">+</div>':''}</div>`;}).join('');}

function updateTeamDisplay(){$('teamCount').textContent=team.length;$('clearTeamBtn').style.display=team.length>0?'block':'none';$('teamGrid').querySelectorAll('.team-slot').forEach((slot,index)=>{const pokemon=team[index];if(pokemon){const primaryColor=TYPE_COLORS[pokemon.types[0]];const secondaryColor=TYPE_COLORS[pokemon.types[1]||pokemon.types[0]];slot.classList.add('filled');slot.style.background=`linear-gradient(135deg,${primaryColor}40 0%,${secondaryColor}40 100%)`;slot.style.borderColor=primaryColor;slot.innerHTML=`<img src="${pokemon.artwork||pokemon.sprite}" alt="${pokemon.name}" class="sprite"><span class="name">${pokemon.displayName}</span><div class="types">${pokemon.types.map(type=>`<span class="mini-type" style="background-color:${TYPE_COLORS[type]}">${TYPE_ICONS[type]}</span>`).join('')}</div><span class="remove-hint">Click to remove</span>`;}else{slot.classList.remove('filled');slot.style.background='rgba(255,255,255,0.03)';slot.style.borderColor='';slot.innerHTML=`<div class="empty-slot"><span class="icon">+</span><span class="text">Empty</span></div>`;}});}

