/* ===== FONTS ===== */

@font-face {
  font-family: "CyberwayRiders";
  src: url("https://xznm6a1vqn.ufs.sh/f/mXkbqgXQWqH1o0D83JRyCJ3v1P20d5OQaRGILftH7BumFKek")
    format("woff");
}

/* ===== BASE STYLES ===== */
body {
  font-family: "Space Grotesk", sans-serif;
  background-color: #0e001a;
  overflow: hidden;
  margin: 0;
  height: 100%;
  color: #bdb7da;
}

h1,
h2,
.menu-button,
.back-button,
#muteButton {
  font-family: "CyberwayRiders", sans-serif;
}

.subtitle {
  font-size: 14px;
  letter-spacing: 0.15em;
  font-weight: 400;
  color: #c3acf1;
  font-family: "Space Grotesk", sans-serif;
}

.logo {
  margin-bottom: 8px;
}

*:focus {
  outline: 2px solid #c082ff;
  outline-offset: 2px;
}

.focus-visible-only:focus:not(:focus-visible) {
  outline: none;
}

.focus-visible-only:focus-visible {
  outline: 2px solid #c082ff;
  outline-offset: 2px;
}

/* ===== ANIMATIONS ===== */
.flicker-slow {
  animation: flicker-slow 2s infinite alternate;
}

.flicker-fast {
  animation: flicker-fast 1s infinite alternate;
}

@keyframes flicker-slow {
  0%,
  100% {
    opacity: 1;
  }
  20%,
  40%,
  60%,
  80% {
    opacity: 0.8;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes flicker-fast {
  0%,
  100% {
    opacity: 1;
  }
  20%,
  40%,
  60%,
  80% {
    opacity: 0.95;
  }
  50% {
    opacity: 0.9;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(20px);
  }
}

@keyframes glitchEffect {
  0% {
    box-shadow: inset 0 0 0 transparent;
  }
  25% {
    box-shadow: inset -3px 0 0 #ff00ea;
  }
  50% {
    box-shadow: inset 3px 0 0 #00ffff;
  }
  75% {
    box-shadow: inset -3px 0 0 #ff00ea;
  }
  100% {
    box-shadow: inset 0 0 0 transparent;
  }
}

@keyframes glowScan {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes loading {
  0% {
    left: -30%;
  }
  100% {
    left: 100%;
  }
}

@keyframes pulse {
  0% {
    opacity: 0.7;
    transform: scale(0.95);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes errorGlitch {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes errorPulse {
  0% {
    opacity: 0.7;
  }
  100% {
    opacity: 1;
  }
}

@keyframes helpPulse {
