@font-face {
  font-family: "Ryze";
  src: url("https://xznm6a1vqn.ufs.sh/f/mXkbqgXQWqH1YrXpefq64iZSgsnw185q2TzvcjHQpVOrfBNh")
    format("woff");
}

@font-face {
  font-family: "CyberwayRiders";
  src: url("https://xznm6a1vqn.ufs.sh/f/mXkbqgXQWqH1o0D83JRyCJ3v1P20d5OQaRGILftH7BumFKek")
    format("woff");
}

/* ==================== BASE STYLES ==================== */
body {
  font-family: "Space Grotesk", sans-serif;
  background-color: #0e001a;
  overflow: hidden;
  margin: 0;
  height: 100%;
  color: #bdb7da;
}

h1, h2, .menu-button, .back-button, #muteButton {
  font-family: "CyberwayRiders", sans-serif;
}

.subtitle {
  font-size: 0.85rem;
  letter-spacing: 0.15em;
  font-weight: 400;
  color: #c3acf1;
  font-family: "Space Grotesk", sans-serif;
}

.logo {
  margin-bottom: 0.5rem;
}

*:focus {
  outline: 2px solid #c082ff;
  outline-offset: 2px;
}

.focus-visible-only:focus:not(:focus-visible) {
  outline: none;
}

.focus-visible-only:focus-visible {
  outline: 2px solid #c082ff;
  outline-offset: 2px;
}

/* ==================== ANIMATIONS ==================== */
.flicker-slow {
  animation: flicker-slow 2s infinite alternate;
}

.flicker-fast {
  animation: flicker-fast 1s infinite alternate;
}

@keyframes flicker-slow {
  0%, 100% {
    opacity: 1;
  }
  20%, 40%, 60%, 80% {
    opacity: 0.8;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes flicker-fast {
  0%, 100% {
    opacity: 1;
  }
  20%, 40%, 60%, 80% {
    opacity: 0.95;
  }
  50% {
    opacity: 0.9;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(20px);
  }
}

@keyframes glitchEffect {
  0% {
    box-shadow: inset 0 0 0 transparent;
  }
  25% {
    box-shadow: inset -3px 0 0 #ff00ea;
  }
  50% {
    box-shadow: inset 3px 0 0 #00ffff;
  }
  75% {
    box-shadow: inset -3px 0 0 #ff00ea;
  }
  100% {
    box-shadow: inset 0 0 0 transparent;
  }
}

@keyframes glowScan {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes loading {
  0% {
    left: -30%;
  }
  100% {
    left: 100%;
  }
}

@keyframes pulse {
  0% {
    opacity: 0.7;
    transform: scale(0.95);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes errorGlitch {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

@keyframes errorPulse {
  0% { opacity: 0.7; }
  100% { opacity: 1; }
}

@keyframes helpPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(192, 130, 255, 0.4);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(192, 130, 255, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(192, 130, 255, 0);
  }
}

/* ==================== BACKGROUND & OVERLAYS ==================== */
#parallax-bg {
  background-image: url("https://xznm6a1vqn.ufs.sh/f/mXkbqgXQWqH1gSSdZnrBDydIz1LF9njxuQaHtYlU0Msc7iXV");
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  filter: brightness(0.35);
}

/* ==================== BUTTONS ==================== */
.menu-button, .back-button, #muteButton {
  font-size: 24px;
  padding: 0.2rem 1rem;
  color: #dcd6f7;
  background: transparent;
  border: none;
  text-shadow: 0 0 5px #c082ff;
  transition: all 0.3s ease;
  cursor: pointer;
  border: 2px solid transparent;
}

.menu-button:hover, .back-button:hover, #muteButton:hover {
  color: black;
  background-color: rgba(255, 255, 255, 0.8);
  border: 2px solid #c082ff;
}

#muteButton {
  position: fixed;
  top: 10px;
  right: 10px;
  font-size: 1.5rem;
  padding: 0.25rem 0.5rem;
}

.back-button {
  display: block;
  margin: 2rem auto 0;
  width: fit-content;
  min-width: 50px;
  position: relative;
  z-index: 10;
}

@media (max-width: 640px) {

.back-button {
  position: absolute;
  top: -30px;
  left: 10px;
  z-index: 1001;
  width: 35px;
  height: 35px;
  border-radius: 0%;
  background: rgba(30, 0, 60, 0.7);
  border: 1px solid #9d4edd;
  color: #d8b4fe;
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(10px);
  box-shadow: 0 0 10px rgba(157, 78, 221, 0.5);
  transition: all 0.3s ease;
  padding: 0;
  margin: 0;
}

.back-button:hover {
  background: rgba(60, 10, 100, 0.8);
  transform: scale(1.05);
  box-shadow: 0 0 15px rgba(157, 78, 221, 0.7);
  color: #ffffff;
}


  #works {
    padding-bottom: 100px;
  }
}

#works h2 {
  position: relative;
}


/* ==================== LAYOUT & SECTION CONTROLS ==================== */
.hidden-section {
  display: none;
}

.fade-in {
  animation: fadeIn 0.5s ease forwards;
}

.fade-out {
  animation: fadeOut 0.5s ease forwards;
}

/* ==================== CODE PREVIEW COMPONENTS ==================== */
.code-preview-icons {
  display: flex;
  gap: 8px;
}

.code-icon {
  background-color: rgba(0, 0, 0, 0.5);
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #c082ff;
  font-size: 14px;
  cursor: pointer;
  pointer-events: auto;
  position: relative;
  z-index: 10;
  transition: all 0.2s ease;
  border: 1px solid rgba(192, 130, 255, 0.3);
}

.code-icon:hover {
  background-color: rgba(192, 130, 255, 0.3);
  transform: translateY(-2px);
}

.preview-icon {
  background-color: rgba(123, 63, 255, 0.3) !important;
  border: 1px solid rgba(192, 130, 255, 0.5) !important;
}

.preview-icon:hover {
  background-color: rgba(192, 130, 255, 0.5) !important;
  transform: translateY(-2px);
}

/* ==================== CODE MODAL ==================== */
.code-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.code-modal.active {
  opacity: 1;
  pointer-events: auto;
}

.code-modal-content {
  background-color: #121212;
  max-height: 80vh;
  overflow-y: auto;
  border-radius: 8px;
  border: 1px solid #7b3fff;
  box-shadow: 0 0 20px rgba(123, 63, 255, 0.5);
}

.code-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  background-color: #1e1e2d;
  border-bottom: 1px solid #3a3a5a;
}

.code-modal-body {
  padding: 20px;
  font-family: "Courier New", monospace;
  white-space: pre;
  overflow-x: auto;
  background-color: #1e1e1e;
  color: #d4d4d4;
  max-height: 60vh;
  text-align: left;
  tab-size: 2;
}

.close-modal {
  background: transparent;
  border: none;
  color: #c082ff;
  font-size: 24px;
  cursor: pointer;
}

.close-modal:hover {
  color: #d2a8ff;
}

/* ==================== ADMIN ACCESS AREA ==================== */
.admin-access-area {
  position: fixed;
  bottom: 5px;
  left: 15px;
  width: 60px;
  height: 60px;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
}

.admin-access-btn {
  opacity: 0;
  visibility: hidden;
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: rgba(0, 0, 0, 0.5);
  padding: 8px 8px;
  border-radius: 9999px;
  border: 1px solid #4b2080;
  transition: all 0.3s ease;
  transform: translateY(10px);
}

.admin-access-area:hover .admin-access-btn {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.admin-access-btn:hover {
  background-color: rgba(143, 63, 251, 0.3);
  border-color: #8f3ffb;
  box-shadow: 0 0 10px rgba(123, 63, 255, 0.5);
}

/* ==================== CYBERPUNK GRID & CARDS ==================== */
.cyberpunk-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  max-height: 70vh;
  overflow-y: auto;
  padding-right: 10px;
  position: relative;
}

.cyberpunk-grid::-webkit-scrollbar {
  width: 6px;
}

.cyberpunk-grid::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 10px;
}

.cyberpunk-grid::-webkit-scrollbar-thumb {
  background: #7b3fff;
  border-radius: 10px;
  box-shadow: 0 0 5px #c082ff;
}

.cyberpunk-grid::-webkit-scrollbar-thumb:hover {
  background: #9b5fff;
}

.cyberpunk-grid::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    to bottom,
    transparent 50%,
    rgba(123, 63, 255, 0.03) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
  z-index: 1;
}

.cyberpunk-card {
  background-color: rgba(12, 12, 24, 0.7);
  border: 1px solid #7b3fff;
  border-radius: 8px;
  padding: 12px;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
  box-shadow: 0 0 15px rgba(123, 63, 255, 0.1);
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.cyberpunk-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, #c082ff, transparent);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.cyberpunk-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(123, 63, 255, 0.3);
  border-color: #c082ff;
}

.cyberpunk-card:hover::before {
  opacity: 1;
  animation: glowScan 2s linear infinite;
}

.cyberpunk-card img {
  width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: 4px;
  margin-bottom: 12px;
  border: 1px solid rgba(123, 63, 255, 0.3);
}

.cyberpunk-card:hover img {
  box-shadow: 0 0 15px rgba(123, 63, 255, 0.5);
  border-color: #9b5fff;
}

.cyberpunk-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: #dcd6f7;
  font-family: "Chakra Petch", sans-serif;
  letter-spacing: 0.5px;
}

.cyberpunk-card .date {
  font-size: 0.75rem;
  color: #9b5fff;
  margin-bottom: 8px;
}

.cyberpunk-card .description {
  font-size: 0.875rem;
  color: #bdb7da;
  margin-bottom: 12px;
  flex-grow: 1;
}

.cyberpunk-card .tech-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.cyberpunk-card .tech-tag {
  background-color: rgba(123, 63, 255, 0.3);
  color: #dcd6f7;
  font-size: 0.7rem;
  border-radius: 12px;
  padding: 3px 8px;
  border: 1px solid rgba(192, 130, 255, 0.3);
}

.cyberpunk-card .controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.cyberpunk-card .code-icon {
  pointer-events: auto;
}

/* ==================== LOADING SCREEN ==================== */
.loading-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(14, 0, 26, 0.9);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  backdrop-filter: blur(8px);
  transition: opacity 0.5s ease;
}

.loading-logo {
  width: 80px;
  height: 80px;
  margin-bottom: 20px;
  animation: pulse 2s infinite alternate;
}

.loading-bar-container {
  width: 200px;
  height: 4px;
  background-color: rgba(123, 63, 255, 0.2);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
  margin-bottom: 15px;
  box-shadow: 0 0 10px rgba(192, 130, 255, 0.3);
}

.loading-bar {
  height: 100%;
  width: 30%;
  background: linear-gradient(90deg, #7b3fff, #c082ff);
  border-radius: 4px;
  position: absolute;
  animation: loading 1.5s infinite;
}

.loading-text {
  font-family: 'Space Grotesk', sans-serif;
  color: #c3acf1;
  font-size: 14px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  animation: flicker-fast 1s infinite alternate;
}

.hide-loading {
  opacity: 0;
  pointer-events: none;
}

/* ==================== QUICK NAVIGATION ==================== */
.quick-nav {
  position: fixed;
  bottom: 20px;
  right: 20px;
  z-index: 100;
}

.quick-nav-toggle {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background: rgba(12, 12, 24, 0.7);
  border: 1px solid #7b3fff;
  color: #c082ff;
  font-size: 20px;
  cursor: pointer;
  box-shadow: 0 0 10px rgba(123, 63, 255, 0.3);
  transition: all 0.3s ease;
}

.quick-nav-toggle:hover {
  box-shadow: 0 0 15px rgba(192, 130, 255, 0.6);
  transform: scale(1.05);
}

.quick-nav-menu {
  position: absolute;
  bottom: 55px;
  right: 0;
  background: rgba(12, 12, 24, 0.8);
  border: 1px solid #7b3fff;
  border-radius: 8px;
  padding: 10px;
  display: none;
  flex-direction: column;
  gap: 8px;
  backdrop-filter: blur(8px);
  box-shadow: 0 0 20px rgba(123, 63, 255, 0.3);
}

.quick-nav-menu.active {
  display: flex;
}

.quick-nav-item {
  color: #c082ff;
  background: transparent;
  border: 1px solid rgba(123, 63, 255, 0.3);
  padding: 6px 12px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: "Chakra Petch", sans-serif;
  font-size: 0.9rem;
}

.quick-nav-item:hover {
  background: rgba(123, 63, 255, 0.2);
  border-color: #c082ff;
}

/* ==================== SOCIAL LINKS ==================== */
.social-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 15px;
  margin-bottom: 20px;
}

.social-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 20px;
  background: rgba(123, 63, 255, 0.1);
  color: #c082ff;
  text-decoration: none;
  transition: all 0.3s ease;
  border: 1px solid rgba(123, 63, 255, 0.3);
}

.social-link:hover {
  background: rgba(123, 63, 255, 0.2);
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(123, 63, 255, 0.2);
}

.social-link i {
  font-size: 1.2rem;
}

.social-label {
  font-size: 0.85rem;
  font-family: "Chakra Petch", sans-serif;
}

/* ==================== SEARCH COMPONENT ==================== */
.search-container {
  margin-bottom: 20px;
  display: flex;
  max-width: 400px;
  margin-left: auto;
  margin-right: auto;
}

.search-input {
  background: rgba(12, 12, 24, 0.7);
  border: 1px solid #7b3fff;
  border-radius: 4px 0 0 4px;
  padding: 8px 12px;
  color: #dcd6f7;
  flex-grow: 1;
  font-family: "Space Grotesk", sans-serif;
  outline: none;
}

.search-input:focus {
  border-color: #c082ff;
  box-shadow: 0 0 10px rgba(123, 63, 255, 0.3);
}

.search-button {
  background: rgba(123, 63, 255, 0.3);
  border: 1px solid #7b3fff;
  border-left: none;
  border-radius: 0 4px 4px 0;
  padding: 8px 12px;
  color: #dcd6f7;
  cursor: pointer;
  transition: all 0.2s ease;
}

.search-button:hover {
  background: rgba(123, 63, 255, 0.5);
}

/* ==================== ERROR COMPONENT ==================== */
.cyberpunk-error {
  background: rgba(12, 12, 24, 0.8);
  border: 1px solid #ff3366;
  border-radius: 8px;
  padding: 15px;
  display: flex;
  align-items: center;
  gap: 15px;
  margin: 10px 0;
  box-shadow: 0 0 15px rgba(255, 51, 102, 0.3);
  position: relative;
  overflow: hidden;
}

.cyberpunk-error::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 51, 102, 0.1), transparent);
  opacity: 0;
  z-index: 1;
}

.cyberpunk-error.glitch-active::before {
  animation: errorGlitch 2s linear infinite;
  opacity: 1;
}

.error-icon {
  font-size: 1.8rem;
  color: #ff3366;
  animation: errorPulse 2s infinite alternate;
}

.error-content {
  text-align: left;
  flex-grow: 1;
}

.error-title {
  font-family: "CyberwayRiders", sans-serif;
  font-size: 1.2rem;
  color: #ff3366;
  margin-bottom: 5px;
}

.error-message {
  color: #e0d8ff;
  font-size: 0.9rem;
  margin-bottom: 8px;
}

.error-action {
  background: rgba(255, 51, 102, 0.2);
  color: #ff3366;
  border: 1px solid rgba(255, 51, 102, 0.5);
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.error-action:hover {
  background: rgba(255, 51, 102, 0.3);
  transform: translateY(-1px);
}

/* ==================== HELP COMPONENT ==================== */
.help-container {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-bottom: 30px;
}

.help-item {
  background: rgba(12, 12, 24, 0.7);
  border: 1px solid #7b3fff;
  border-radius: 8px;
  padding: 15px;
  transition: all 0.3s ease;
}

.help-item:hover {
  border-color: #c082ff;
  box-shadow: 0 0 15px rgba(123, 63, 255, 0.3);
}

.help-question {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.help-question i {
  color: #c082ff;
  font-size: 1.2rem;
}

.help-question h3 {
  font-family: "Chakra Petch", sans-serif;
  color: #e0d8ff;
  font-size: 1.1rem;
  font-weight: 600;
}

.help-answer p {
  color: #bdb7da;
  font-size: 0.95rem;
  line-height: 1.5;
}

.key {
  background: rgba(123, 63, 255, 0.2);
  border: 1px solid #7b3fff;
  border-radius: 4px;
  padding: 2px 6px;
  font-family: "Chakra Petch", sans-serif;
  font-size: 0.8rem;
  color: #e0d8ff;
  display: inline-block;
  margin: 0 2px;
}

.keyboard-shortcuts {
  background: rgba(12, 12, 24, 0.5);
  border: 1px solid #7b3fff;
  border-radius: 8px;
  padding: 15px;
}

.shortcut-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
}

.shortcut {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  color: #bdb7da;
}

.help-hover-menu {
  position: fixed;
  bottom: 20px;
  right: 20px; /* Changed from 75px to 20px to move it to the corner */
  z-index: 100;
}

.help-toggle {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background: rgba(12, 12, 24, 0.7);
  border: 1px solid #7b3fff;
  color: #c082ff;
  font-size: 20px;
  cursor: pointer;
  box-shadow: 0 0 10px rgba(123, 63, 255, 0.3);
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: helpPulse 2s infinite;
}

.help-toggle:hover {
  box-shadow: 0 0 15px rgba(192, 130, 255, 0.6);
  transform: scale(1.05);
}

.help-content {
  position: absolute;
  bottom: 55px;
  right: 0; /* Changed from -25px to 0 to align with the corner */
  width: 320px;
  max-height: 70vh;
  background: rgba(12, 12, 24, 0.95);
  border: 1px solid #7b3fff;
  border-radius: 8px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
  box-shadow: 0 0 20px rgba(123, 63, 255, 0.4);
  overflow: hidden;
  pointer-events: none;
}

/* Desktop hover behavior with better interaction */
@media (hover: hover) {
  .help-hover-menu:hover .help-content {
