const container = document.getElementById("news-container");
const searchInput = document.getElementById("searchInput");
const desktopSearchInput = document.getElementById("desktopSearchInput");
const loader = document.getElementById("loader");
const loadMoreBtn = document.getElementById("load-more");
const paginationControls = document.getElementById("pagination-controls");
const scrollIndicator = document.getElementById("scroll-indicator");
const menuToggle = document.getElementById("menuToggle");
const sidebar = document.getElementById("sidebar");
const sidebarOverlay = document.getElementById("sidebarOverlay");
const closeSidebar = document.getElementById("closeSidebar");
const darkToggleBtn = document.getElementById("darkToggleBtn");
const darkModeToggle = document.getElementById("darkModeToggle");
const searchToggle = document.getElementById("searchToggle");
const searchOverlay = document.getElementById("searchOverlay");
const searchClose = document.getElementById("searchClose");

let allStories = [];
let storyIds = [];
let currentPage = 1;
let itemsPerPage = 20;
let isLoading = false;
let hasMoreStories = true;
let isMobile = window.innerWidth < 768;

function toggleSidebar() {
  sidebar.classList.toggle("active");
  sidebarOverlay.classList.toggle("active");
  document.body.style.overflow = sidebar.classList.contains("active") ? "hidden" : "";
}

function toggleSearch() {
  searchOverlay.classList.toggle("active");
  if (searchOverlay.classList.contains("active")) {
    searchInput.focus();
  }
}

async function fetchTopStories() {
  const res = await fetch('https://hacker-news.firebaseio.com/v0/topstories.json');
  const ids = await res.json();
  const top20 = ids.slice(0, 20);
  const storyPromises = top20.map(id => fetch(`https://hacker-news.firebaseio.com/v0/item/${id}.json`).then(r => r.json()));
  const stories = await Promise.all(storyPromises);

  storyIds = ids;
  allStories = stories;

  if (storyIds.length > 20) {
    paginationControls.style.display = 'flex';
    hasMoreStories = true;
  }

  return stories;
}

async function loadMoreStories() {
  if (isLoading || !hasMoreStories) return;

  try {
    isLoading = true;
    loadMoreBtn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Loading...';

    const startIndex = currentPage * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageIds = storyIds.slice(startIndex, endIndex);

    if (pageIds.length === 0) {
      hasMoreStories = false;
      paginationControls.style.display = 'none';
      isLoading = false;
      return;
    }

    const storyPromises = pageIds.map(id => 
      fetch(`https://hacker-news.firebaseio.com/v0/item/${id}.json`).then(r => r.json())
    );

    const stories = await Promise.all(storyPromises);
    const validStories = stories.filter(item => item && item.title);

    appendStories(validStories);

    currentPage++;

    if (endIndex >= storyIds.length) {
      hasMoreStories = false;
      paginationControls.style.display = 'none';
    }

    loadMoreBtn.innerHTML = 'Load More';
    isLoading = false;
  } catch (error) {
    console.error("Error loading more stories:", error);
    loadMoreBtn.innerHTML = 'Error loading stories';
    isLoading = false;
  }
}

function renderStories(stories) {
  loader.style.display = 'none';
  container.innerHTML = '';
  stories.forEach((item, index) => {
    if (!item || !item.title) return;
    const card = document.createElement("div");
    card.className = "news-card";
    card.innerHTML = `
      <div class="d-flex justify-content-between align-items-start">
        <div>
          <span class="text-secondary fw-bold">${index + 1}.</span>
          <a href="${item.url || '#'}" class="h5 text-decoration-none ms-2" target="_blank" rel="noopener noreferrer">${item.title}</a>
          <div class="news-meta"><span class="vote-count">${item.score || 0}</span> points by ${item.by || 'unknown'} • ${formatTime(item.time)}</div>
        </div>
        <div class="vote-btn" title="Upvote">▲</div>
      </div>
    `;
    container.appendChild(card);
  });
}

function appendStories(stories) {
  const startIndex = allStories.length;

  stories.forEach((item, index) => {
    if (!item || !item.title) return;
    allStories.push(item);

    const card = document.createElement("div");
    card.className = "news-card fade-in";
    card.innerHTML = `
      <div class="d-flex justify-content-between align-items-start">
        <div>
          <span class="text-secondary fw-bold">${startIndex + index + 1}.</span>
          <a href="${item.url || '#'}" class="h5 text-decoration-none ms-2" target="_blank" rel="noopener noreferrer">${item.title}</a>
          <div class="news-meta"><span class="vote-count">${item.score || 0}</span> points by ${item.by || 'unknown'} • ${formatTime(item.time)}</div>
        </div>
        <div class="vote-btn" title="Upvote">▲</div>
      </div>
    `;
    container.appendChild(card);
  });
}

function formatTime(timestamp) {
  if (!timestamp) return '';
  const now = new Date();
  const date = new Date(timestamp * 1000);
  const diffMs = now - date;
  const diffMins = Math.floor(diffMs / 60000);

  if (diffMins < 60) {
    return `${diffMins} minute${diffMins !== 1 ? 's' : ''} ago`;
  } else if (diffMins < 24 * 60) {
    const hours = Math.floor(diffMins / 60);
    return `${hours} hour${hours !== 1 ? 's' : ''} ago`;
  } else {
    const days = Math.floor(diffMins / (60 * 24));
    if (days < 30) {
      return `${days} day${days !== 1 ? 's' : ''} ago`;
    } else {
      return date.toLocaleDateString();
    }
  }
}

function filterStories(stories, query) {
  return stories.filter(item => item.title.toLowerCase().includes(query.toLowerCase()));
}

function handleScroll() {

  const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;

  if (scrollTop > 300) {
    scrollIndicator.classList.add('visible');
  } else {
    scrollIndicator.classList.remove('visible');
  }
}

function toggleDarkMode() {
  const html = document.documentElement;
  const isDark = html.getAttribute("data-bs-theme") === "dark";
  const newTheme = isDark ? "light" : "dark";
  html.setAttribute("data-bs-theme", newTheme);
  document.body.style.backgroundColor = newTheme === "dark" ? '#121212' : '#fff';

  const themeIcons = document.querySelectorAll(".dark-mode-toggle i, #darkToggleBtn i");
  themeIcons.forEach(icon => {
    icon.classList.remove('bi-moon', 'bi-sun');
    icon.classList.add(newTheme === 'dark' ? 'bi-sun' : 'bi-moon');
  });

  localStorage.setItem("theme", newTheme);

  if (isMobile && sidebar.classList.contains("active")) {
    toggleSidebar();
  }
}

function handleResize() {
  isMobile = window.innerWidth < 768;

  if (!isMobile && sidebar.classList.contains("active")) {
    sidebar.classList.remove("active");
    sidebarOverlay.classList.remove("active");
    document.body.style.overflow = "";
  }
}

window.addEventListener("DOMContentLoaded", () => {
  const savedTheme = localStorage.getItem("theme") || "light";
  document.documentElement.setAttribute("data-bs-theme", savedTheme);
  document.body.style.backgroundColor = savedTheme === "dark" ? '#121212' : '#fff';

  const themeIcons = document.querySelectorAll(".dark-mode-toggle i, #darkToggleBtn i");
  themeIcons.forEach(icon => {
    icon.classList.remove('bi-moon', 'bi-sun');
    icon.classList.add(savedTheme === "dark" ? 'bi-sun' : 'bi-moon');
  });

  fetchTopStories().then(stories => {
    renderStories(stories);
    window.addEventListener('scroll', handleScroll);
  });

  handleResize();
});

darkToggleBtn.addEventListener("click", toggleDarkMode);
if (darkModeToggle) {
  darkModeToggle.addEventListener("click", toggleDarkMode);
}

menuToggle.addEventListener("click", toggleSidebar);
closeSidebar.addEventListener("click", toggleSidebar);
sidebarOverlay.addEventListener("click", toggleSidebar);
searchToggle.addEventListener("click", toggleSearch);
searchClose.addEventListener("click", toggleSearch);
window.addEventListener("resize", handleResize);

loadMoreBtn.addEventListener("click", () => {
  loadMoreStories();
});

desktopSearchInput.addEventListener("input", () => {
  const filtered = filterStories(allStories, desktopSearchInput.value);
  renderStories(filtered);
  paginationControls.style.display = desktopSearchInput.value ? 'none' : (hasMoreStories ? 'flex' : 'none');
});

searchInput.addEventListener("input", () => {
  desktopSearchInput.value = searchInput.value;
});

desktopSearchInput.addEventListener("input", () => {
  searchInput.value = desktopSearchInput.value;
});

document.querySelectorAll('.nav-links a').forEach(link => {
  link.addEventListener('click', () => {
    if (isMobile && sidebar.classList.contains("active")) {
      toggleSidebar();
    }
  });
});

scrollIndicator.addEventListener('click', () => {
  window.scrollTo({
    top: 0,
    behavior: 'smooth'
  });
});

